/**
 * Task 15B maintenance case states are evidence-backed workflow states, not
 * descriptions generated by a model. One case is one operating_tasks row.
 * The signed, append-only event stream is subordinate to that canonical case.
 */
export const maintenanceStages=[
  "reported","investigating","awaiting_owner","assigned",
  "request_sent","repair_claimed","verified_repaired","blocked","reopened",
] as const;
export type MaintenanceStage=(typeof maintenanceStages)[number];
export const maintenanceEventKinds=[
  "report","investigation","owner_approval_requested","owner_approval_recorded",
  "staff_assignment","vendor_send_verified","repair_claim",
  "operational_verification","blocked","reopened","follow_up",
] as const;
export type MaintenanceEventKind=(typeof maintenanceEventKinds)[number];
export type MaintenanceEvidence={
  source:"staff_report"|"owner_report"|"supervisor_read"|"approved_staff_assignment"|
    "gmail_effect_receipt"|"vendor_reply"|"owner_operational_check"|"staff_operational_check"|
    "system_follow_up";
  sourceId:string;
  observedAt:string;
};
export type MaintenanceEvent={
  kind:MaintenanceEventKind;
  evidence:MaintenanceEvidence;
  actor:"owner"|"staff"|"supervisor"|"vendor";
  /** Only verified receipts from the existing Supervisor effect gateway qualify. */
  approvalId?:string;
  providerReceiptId?:string;
  /** An independent check of working equipment, never the vendor's repair claim. */
  workingConfirmed?:boolean;
};
export type MaintenanceTransition={
  stage:MaintenanceStage;
  /** A repair claimed by a vendor is NOT independently verified completion. */
  repaired:boolean;
  externalSent:boolean;
};
const nonempty=(value:unknown):value is string=>
  typeof value==="string"&&value.trim().length>0&&value.length<=256;
/**
 * Small deterministic transition policy for the sole maintenance case.
 * Validation is repeated in the database: this function is never an authority
 * for an external send or an authenticated staff/owner permission.
 */
export function advanceMaintenanceCase(
  before:MaintenanceTransition,event:MaintenanceEvent,
):MaintenanceTransition{
  if(!nonempty(event.evidence.sourceId)||
    !Number.isFinite(Date.parse(event.evidence.observedAt)))
    throw new Error("maintenance_evidence_missing");
  const {kind,evidence}=event;
  const current=before.stage;
  if(kind==="report"){
    if(current!=="reported"&&current!=="reopened")throw new Error("case_already_open");
    if(!["staff_report","owner_report"].includes(evidence.source))throw new Error("invalid_report_source");
    return {stage:"reported",repaired:false,externalSent:false};
  }
  if(kind==="investigation"){
    if(current==="verified_repaired")throw new Error("case_already_resolved");
    if(evidence.source!=="supervisor_read")throw new Error("investigation_not_attested");
    return {...before,stage:"investigating"};
  }
  if(kind==="owner_approval_requested"){
    if(current==="verified_repaired")throw new Error("case_already_resolved");
    return {...before,stage:"awaiting_owner"};
  }
  if(kind==="owner_approval_recorded"){
    // Approval is recorded from the real gateway, not merely model text.
    if(event.actor!=="owner"||!nonempty(event.approvalId))
      throw new Error("owner_approval_required");
    return before;
  }
  if(kind==="staff_assignment"){
    if(evidence.source!=="approved_staff_assignment"||!nonempty(event.approvalId))
      throw new Error("staff_assignment_not_authorized");
    if(current==="verified_repaired")throw new Error("case_already_resolved");
    return {...before,stage:"assigned"};
  }
  if(kind==="vendor_send_verified"){
    if(evidence.source!=="gmail_effect_receipt"||
      !nonempty(event.approvalId)||!nonempty(event.providerReceiptId))
      throw new Error("vendor_send_not_verified");
    if(current==="verified_repaired")throw new Error("case_already_resolved");
    return {...before,stage:"request_sent",externalSent:true};
  }
  if(kind==="repair_claim"){
    if(evidence.source!=="vendor_reply"&&evidence.source!=="staff_report")
      throw new Error("repair_claim_source_invalid");
    if(current==="verified_repaired")throw new Error("case_already_resolved");
    return {...before,stage:"repair_claimed",repaired:false};
  }
  if(kind==="operational_verification"){
    if(current!=="repair_claimed")throw new Error("repair_claim_required");
    if(!event.workingConfirmed||
      !["owner_operational_check","staff_operational_check"].includes(evidence.source)||
      !["owner","staff"].includes(event.actor))
      throw new Error("independent_operational_check_required");
    return {...before,stage:"verified_repaired",repaired:true};
  }
  if(kind==="blocked")return {...before,stage:"blocked",repaired:false};
  if(kind==="reopened"){
    if(current!=="verified_repaired"&&current!=="blocked")
      throw new Error("reopen_requires_closed_or_blocked");
    return {stage:"reopened",repaired:false,externalSent:false};
  }
  if(kind==="follow_up")return before;
  throw new Error("invalid_maintenance_event");
}
export const initialMaintenanceTransition:MaintenanceTransition={
  stage:"reported",repaired:false,externalSent:false,
};
